-- M1.1 Catalog & floor schema (docs/architecture/data-model.md "Menu and floor", docs/requirements/m1.1-scope.md).
-- Items, categories, groups, tables, stations and areas are never deleted, only deactivated.
-- Conventions as in V1: UUID ids generated by the app, branch_id, timestamptz, version for optimistic locking.

CREATE TABLE kitchen_station (
    id                  uuid PRIMARY KEY,
    branch_id           uuid         NOT NULL REFERENCES branch (id),
    number              int          NOT NULL CHECK (number BETWEEN 1 AND 3),
    name                varchar(50)  NOT NULL,
    target_prep_minutes int          NOT NULL CHECK (target_prep_minutes BETWEEN 1 AND 240),
    active              boolean      NOT NULL DEFAULT true,
    version             int          NOT NULL DEFAULT 0,
    created_at          timestamptz  NOT NULL DEFAULT now(),
    updated_at          timestamptz  NOT NULL DEFAULT now(),
    created_by          uuid,
    updated_by          uuid,
    UNIQUE (branch_id, number)
);
CREATE UNIQUE INDEX ux_kitchen_station_name ON kitchen_station (branch_id, lower(name));

CREATE TABLE ordering_point (
    id         uuid PRIMARY KEY,
    branch_id  uuid        NOT NULL REFERENCES branch (id),
    name       varchar(50) NOT NULL,
    sort_order int         NOT NULL,
    UNIQUE (branch_id, name)
);

CREATE TABLE category (
    id         uuid PRIMARY KEY,
    branch_id  uuid        NOT NULL REFERENCES branch (id),
    name       varchar(50) NOT NULL,
    sort_order int         NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
    active     boolean     NOT NULL DEFAULT true,
    version    int         NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_by uuid
);
CREATE UNIQUE INDEX ux_category_name ON category (branch_id, lower(name));

CREATE TABLE modifier_group (
    id         uuid PRIMARY KEY,
    branch_id  uuid        NOT NULL REFERENCES branch (id),
    name       varchar(50) NOT NULL,
    required   boolean     NOT NULL,
    min_select int         NOT NULL CHECK (min_select >= 0),
    max_select int         NOT NULL CHECK (max_select >= 1),
    active     boolean     NOT NULL DEFAULT true,
    version    int         NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_by uuid,
    CHECK (max_select >= min_select),
    CHECK (required = (min_select >= 1))
);
CREATE UNIQUE INDEX ux_modifier_group_name ON modifier_group (branch_id, lower(name));

CREATE TABLE modifier_option (
    id          uuid PRIMARY KEY,
    group_id    uuid          NOT NULL REFERENCES modifier_group (id) ON DELETE CASCADE,
    name        varchar(50)   NOT NULL,
    price_delta numeric(12,2) NOT NULL DEFAULT 0 CHECK (price_delta >= 0),
    sort_order  int           NOT NULL,
    version     int           NOT NULL DEFAULT 0,
    created_at  timestamptz   NOT NULL DEFAULT now(),
    updated_at  timestamptz   NOT NULL DEFAULT now(),
    created_by  uuid,
    updated_by  uuid
);
CREATE INDEX ix_modifier_option_group ON modifier_option (group_id, sort_order);

CREATE TABLE menu_item (
    id                 uuid PRIMARY KEY,
    branch_id          uuid         NOT NULL REFERENCES branch (id),
    code               varchar(20)  NOT NULL,
    name               varchar(100) NOT NULL,
    category_id        uuid         NOT NULL REFERENCES category (id),
    kitchen_station_id uuid         NOT NULL REFERENCES kitchen_station (id),   -- exactly one station (P1-MENU-02)
    active             boolean      NOT NULL DEFAULT true,
    available          boolean      NOT NULL DEFAULT true,                       -- false = sold out today
    version            int          NOT NULL DEFAULT 0,
    created_at         timestamptz  NOT NULL DEFAULT now(),
    updated_at         timestamptz  NOT NULL DEFAULT now(),
    created_by         uuid,
    updated_by         uuid,
    UNIQUE (branch_id, code)
);
CREATE INDEX ix_menu_item_category ON menu_item (category_id);
CREATE INDEX ix_menu_item_station ON menu_item (kitchen_station_id) WHERE active;

CREATE TABLE menu_item_price (
    menu_item_id uuid          NOT NULL REFERENCES menu_item (id) ON DELETE CASCADE,
    price_list   varchar(10)   NOT NULL CHECK (price_list IN ('LOCAL', 'FOREIGN')),
    price        numeric(12,2) NOT NULL CHECK (price >= 0),
    PRIMARY KEY (menu_item_id, price_list)
);

CREATE TABLE menu_item_modifier_group (
    menu_item_id      uuid NOT NULL REFERENCES menu_item (id) ON DELETE CASCADE,
    modifier_group_id uuid NOT NULL REFERENCES modifier_group (id),
    sort_order        int  NOT NULL,
    PRIMARY KEY (menu_item_id, sort_order),
    UNIQUE (menu_item_id, modifier_group_id)
);

CREATE TABLE dining_table (
    id         uuid PRIMARY KEY,
    branch_id  uuid        NOT NULL REFERENCES branch (id),
    number     varchar(10) NOT NULL,
    section    varchar(30) NOT NULL,
    seats      int         NOT NULL CHECK (seats BETWEEN 1 AND 50),
    pos_x      int         NOT NULL CHECK (pos_x BETWEEN 0 AND 1000),    -- centre of the table on the 1000 x 700 grid
    pos_y      int         NOT NULL CHECK (pos_y BETWEEN 0 AND 700),
    active     boolean     NOT NULL DEFAULT true,
    version    int         NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_by uuid
);
CREATE UNIQUE INDEX ux_dining_table_number ON dining_table (branch_id, lower(number));

-- Settings tables created in V1: names / texts are unique so imports and editors can match on them.
CREATE UNIQUE INDEX ux_delivery_area_name ON delivery_area (branch_id, lower(name));
CREATE UNIQUE INDEX ux_reason_text ON reason (branch_id, category, lower(text));

-- Terminals can now point at real stations and ordering points. NOT VALID: the constraint applies to new and
-- changed rows; terminals registered before M1.1 (which had no stations to point at) are not re-checked.
ALTER TABLE terminal ADD CONSTRAINT fk_terminal_station FOREIGN KEY (kitchen_station_id) REFERENCES kitchen_station (id) NOT VALID;
ALTER TABLE terminal ADD CONSTRAINT fk_terminal_ordering_point FOREIGN KEY (ordering_point_id) REFERENCES ordering_point (id) NOT VALID;
